const item = $input.item.json;

// Safely handle n8n webhook data structure (whether top-level or nested in .body)
const payload = (item.body && typeof item.body === 'object') ? item.body : item;

// Extract and ensure each field is a clean primitive string
const subject = payload.subject ? String(payload.subject) : "No Subject Found";
const sender = payload.sender ? String(payload.sender) : "Unknown Sender";
const body = payload.body && typeof payload.body === 'string' 
    ? payload.body 
    : (payload.text ? String(payload.text) : JSON.stringify(payload.body || payload));

return {
    subject: subject,
    sender: sender,
    body: body
};

const item = $input.item.json;

// Extract raw data from Gemini's output field
let rawOutput = item.text || item.output || item.response || item.content || (item.message && item.message.content) || item;

// Ensure it is safely converted to a string
let aiOutput = typeof rawOutput === 'string' ? rawOutput : JSON.stringify(rawOutput);

// Clean markdown code blocks
let cleanText = aiOutput.replace(/```json/gi, '').replace(/```/g, '').trim();

let score = 50;
let verdict = "Analyzed";
let reason = cleanText; // Defaults to printing Gemini's exact output message directly

try {
    // If Gemini outputted a JSON block, extract the fields safely
    const jsonMatch = cleanText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        score = Number(parsed.risk_score ?? parsed.score ?? 50);
        verdict = parsed.verdict ?? "Analyzed";
        reason = parsed.reason ?? cleanText; // Uses Gemini's reason text if available
    }
} catch (e) {
    // If it's plain text, it passes Gemini's exact message straight through as the reason
    reason = cleanText;
}

return {
    score: score,
    verdict: verdict,
    reason: reason
};

